  private void ensureFamilyMetadata() throws IOException {
    if (this.familiesInitialized) {
      return;
    }

    Map<String, String> parents = new LinkedHashMap<>();
    Set<String> ownNames = new LinkedHashSet<>();
    for (Map.Entry<String, List<ContextUnit>> entry : this.candidatesByClassName.entrySet()) {
      for (ContextUnit unit : entry.getValue()) {
        if (!unit.isOwn()) {
          continue;
        }
        ownNames.add(entry.getKey());
        byte[] bytes = getClassBytes(unit, entry.getKey());
        if (bytes == null) {
          continue;
        }
        StructClass clazz = StructClass.create(new DataInputFullStream(bytes), true);
        StructInnerClassesAttribute innerClasses = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_INNER_CLASSES);
        if (innerClasses != null) {
          for (StructInnerClassesAttribute.Entry inner : innerClasses.getEntries()) {
            if (inner.innerName != null && inner.enclosingName != null) {
              parents.putIfAbsent(inner.innerName, inner.enclosingName);
            }
          }
        }
        StructEnclosingMethodAttribute enclosingMethod = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_ENCLOSING_METHOD);
        if (enclosingMethod != null && enclosingMethod.getClassName() != null) {
          parents.putIfAbsent(clazz.qualifiedName, enclosingMethod.getClassName());
        }
      }
    }

    for (String name : ownNames) {
      this.familyRoots.put(name, findFamilyRoot(name, parents));
    }
    for (Map.Entry<String, List<ContextUnit>> entry : this.candidatesByClassName.entrySet()) {
      long ownOrigins = entry.getValue().stream().filter(ContextUnit::isOwn).distinct().count();
      if (ownOrigins > 1) {
        String familyRoot = this.familyRoots.getOrDefault(entry.getKey(), entry.getKey());
        this.coherentFamilies.add(familyRoot);
        this.familyDuplicates.putIfAbsent(familyRoot, entry.getKey());
      }
    }
    this.familiesInitialized = true;
  }

